// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents create, edit and discard drafts"
// Changes: Draft tools at the MCP message level: creating, listing, relabelling and discarding drafts, editing their
//          parts (fresh problems after each edit, the stale expectedRevision rule), the drafts-only rule and read
//          tools on draft targets.

import { describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { agentHarness } from './agentTestHarness'

const h = agentHarness()
const { call, rpc, advance } = h

// E → id | id + E has an LL(1) conflict in cell [E, id].
const expressions = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id\nE -> id + E', input: 'id + id' },
  prec: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' }, rules: 'E -> E + E\nE -> id', input: 'id' },
  names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

const FIXED_GRAMMAR = 'E -> id R\nR -> + E\nR -> eps'

async function newDraft(label = 'Oprava konfliktu') {
  const project = h.store.createProject('Výrazy', expressions())
  const { draft } = await call('create_draft', { project: project.id, label })
  return { project, draft, target: { kind: 'draft', id: draft.id } }
}

describe('discovering draft tools', () => {
  it('tools/list offers the draft tools after the read tools; writing tools are not read-only', async () => {
    const { result } = await rpc('tools/list')
    const tools = result.tools as { name: string; description: string; annotations: any; inputSchema: any }[]
    const names = tools.map((t) => t.name)
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Changes: module, agent tool and text diffs"
    // Changes: get_draft_changes (read-only, changesTool.server.test.ts) sits between the read and the draft tools.
    expect(names[11]).toBe('get_draft_changes')
    expect(names.slice(12)).toEqual([
      'list_drafts',
      'create_draft',
      'relabel_draft',
      'discard_draft',
      'set_definition',
      'set_grammar_rules',
      'set_reduction_rules',
      'set_prec_terminals',
      'set_relation',
      'clear_relations',
    ])
    expect(names).not.toContain('adopt_draft')
    for (const tool of tools.slice(13)) {
      expect(tool.annotations.readOnlyHint).toBe(false)
      expect(tool.description).toMatch(/draft/i)
    }
    expect(tools.find((t) => t.name === 'get_part')!.inputSchema.properties.target.properties.kind.enum).toEqual([
      'project',
      'draft',
      'snapshot',
    ])
  })
})

describe('creating and listing drafts', () => {
  it("an agent creates a draft of a project; it starts from the project's parts and records its base", async () => {
    const project = h.store.createProject('Výrazy', expressions())
    advance(1000)
    const res = await call('create_draft', { project: project.id, label: 'Oprava konfliktu' })
    expect(res).toEqual({
      draft: {
        id: expect.any(String),
        projectId: project.id,
        label: 'Oprava konfliktu',
        state: 'open',
        revision: 1,
        partRevisions: { definition: 1, grammarRules: 1, precTable: 1, reductionRules: 1 },
        lastChangedBy: 'agent',
        base: { projectRevision: 1 },
        createdAt: '2026-01-01T10:00:01.000Z',
        updatedAt: '2026-01-01T10:00:01.000Z',
        endedAt: null,
      },
      target: { kind: 'draft', id: res.draft.id },
    })
    expect(h.store.getProject(project.id)).toEqual(project)
  })

  it('an agent lists the drafts of a project, open and ended', async () => {
    const { project, draft } = await newDraft('A')
    advance(1000)
    const b = await call('create_draft', { project: project.id, label: 'B' })
    await call('discard_draft', { target: { kind: 'draft', id: draft.id } })

    const res = await call('list_drafts', { project: project.id })
    expect(res.project).toEqual({ id: project.id, name: 'Výrazy', revision: 1 })
    expect(res.drafts.map((d: { id: string; state: string }) => [d.id, d.state])).toEqual([
      [b.draft.id, 'open'],
      [draft.id, 'discarded'],
    ])
  })

  it('creating or listing drafts of an unknown project, or with an empty label, gives a clear error', async () => {
    expect((await call('create_draft', { project: 'nope', label: 'x' })).error).toMatch(/no project.*nope/i)
    expect((await call('list_drafts', { project: 'nope' })).error).toMatch(/no project.*nope/i)
    const project = h.store.createProject('Výrazy', expressions())
    expect((await call('create_draft', { project: project.id, label: '  ' })).error).toMatch(/label/i)
  })
})

describe('editing a draft', () => {
  it('an agent fixes the LL conflict through the grammar rules and reads back a conflict-free LL table; the project is unchanged', async () => {
    const { project, target } = await newDraft()
    expect((await call('get_ll_table', { target })).conflicts).toHaveLength(1)

    const res = await call('set_grammar_rules', { target, text: FIXED_GRAMMAR, expectedRevision: 1 })
    expect(res.target).toMatchObject({ kind: 'draft', id: target.id, projectId: project.id, revision: 2 })
    expect(res.revision).toBe(2)
    expect(res.changed).toEqual(['grammarRules'])
    expect(Object.keys(res.problems)).toEqual(['definition', 'll', 'prec'])

    const table = await call('get_ll_table', { target })
    expect(table.conflicts).toEqual([])
    expect(table.rules.map((r: { text: string }) => r.text)).toEqual(['E → id R', 'R → + E', 'R → ε'])

    const projectTable = await call('get_ll_table', { target: { kind: 'project', id: project.id } })
    expect(projectTable.conflicts).toHaveLength(1)
    expect(h.store.getProject(project.id)).toEqual(project)
  })

  it('every edit returns fresh problems: a definition missing R is reported, declaring it clears it', async () => {
    const { target } = await newDraft()
    const afterRules = await call('set_grammar_rules', { target, text: FIXED_GRAMMAR })
    expect(afterRules.problems.definition).toContainEqual({ level: expect.stringMatching(/bad|warn/), text: expect.stringContaining('R') })

    const afterDef = await call('set_definition', { target, nonterminals: 'E\nR', terminals: 'id\n+', start: 'E' })
    expect(afterDef.revision).toBe(3)
    expect(afterDef.changed).toEqual(['definition'])
    expect(afterDef.problems.definition.filter((p: { level: string }) => p.level === 'bad' || p.level === 'warn')).toEqual([])
    expect((await call('get_part', { target, part: 'definition' })).value).toEqual({ nonterminals: 'E\nR', terminals: 'id\n+', start: 'E' })
  })

  it('an agent replaces the reduction rules', async () => {
    const { target } = await newDraft()
    const res = await call('set_reduction_rules', { target, text: 'E -> id' })
    expect(res).toMatchObject({ revision: 2, changed: ['reductionRules'] })
    expect((await call('get_part', { target, part: 'reductionRules' })).value).toBe('E -> id')
  })

  it('an agent edits the precedence table: terminals, single relations and clearing all relations', async () => {
    const { target } = await newDraft()
    await call('set_prec_terminals', { target, terminals: ['+', '*', 'id'] })
    await call('set_relation', { target, stack: '+', input: '*', relation: '<' })
    await call('set_relation', { target, stack: '$', input: 'id', relation: '<' })
    const removed = await call('set_relation', { target, stack: 'id', input: '+', relation: '' })
    expect(removed).toMatchObject({ revision: 5, changed: ['precTable'] })
    expect((await call('get_part', { target, part: 'precTable' })).value).toEqual({
      terminals: ['+', '*', 'id'],
      relations: [
        { stack: '+', input: '*', relation: '<' },
        { stack: '$', input: 'id', relation: '<' },
      ],
    })

    const cleared = await call('clear_relations', { target })
    expect(cleared.revision).toBe(6)
    expect((await call('get_part', { target, part: 'precTable' })).value.relations).toEqual([])
  })

  it('a relation for a terminal the precedence table does not have is refused with the terminals listed', async () => {
    const { target } = await newDraft()
    const res = await call('set_relation', { target, stack: '*', input: 'id', relation: '<' })
    expect(res.error).toMatch(/\*/)
    expect(res.error).toMatch(/\+.*id.*\$/)
    expect((await call('set_relation', { target, stack: '+', input: 'id', relation: '?' })).error).toMatch(/relation/)
  })

  it('an edit that changes nothing keeps the revision', async () => {
    const { target } = await newDraft()
    expect(await call('set_reduction_rules', { target, text: 'E -> E + E\nE -> id' })).toMatchObject({ revision: 1, changed: [] })
  })
})

describe('the stale expectedRevision rule', () => {
  it('a stale expectedRevision is refused, with the current text, only when that part changed since then', async () => {
    const { target } = await newDraft()
    await call('set_grammar_rules', { target, text: FIXED_GRAMMAR }) // revision 2

    // Another writer at revision 1 changes the reduction rules: grammar rules changed since 1, reduction rules didn't.
    expect(await call('set_reduction_rules', { target, text: 'E -> id', expectedRevision: 1 })).toMatchObject({ revision: 3 })

    const refused = await call('set_grammar_rules', { target, text: 'E -> x', expectedRevision: 1 })
    expect(refused).toEqual({
      error: expect.stringMatching(/grammar rules.*changed.*revision 2/i),
      revision: 3,
      part: 'grammarRules',
      partRevision: 2,
      current: FIXED_GRAMMAR,
    })
    expect((await call('get_part', { target, part: 'grammarRules' })).value).toBe(FIXED_GRAMMAR)

    expect(await call('set_grammar_rules', { target, text: 'E -> x', expectedRevision: 3 })).toMatchObject({ revision: 4 })
  })
})

describe('relabelling and discarding', () => {
  it('an agent relabels a draft without changing its revision', async () => {
    const { target } = await newDraft()
    const res = await call('relabel_draft', { target, label: 'Pravá rekurzia' })
    expect(res.draft).toMatchObject({ label: 'Pravá rekurzia', revision: 1 })
  })

  it('an agent discards a draft: it ends with a final snapshot that stays readable', async () => {
    const { project, target } = await newDraft()
    await call('set_grammar_rules', { target, text: FIXED_GRAMMAR })
    advance(1000)

    const res = await call('discard_draft', { target })
    expect(res.draft).toMatchObject({ state: 'discarded', endedAt: '2026-01-01T10:00:01.000Z' })

    const { snapshots } = await call('list_snapshots', { target })
    expect(snapshots[0]).toMatchObject({ kind: 'final', label: 'Zahodený návrh „Oprava konfliktu“' })
    const fromSnapshot = await call('get_part', { target: { kind: 'snapshot', id: snapshots[0].id }, part: 'grammarRules' })
    expect(fromSnapshot.value).toBe(FIXED_GRAMMAR)
    expect(fromSnapshot.target).toMatchObject({ kind: 'snapshot', projectId: project.id, draftId: target.id, snapshotKind: 'final' })
    expect(h.store.getProject(project.id)).toEqual(project)
  })
})

describe('the drafts-only rule', () => {
  it('writes to a project are refused and the project is unchanged', async () => {
    const project = h.store.createProject('Výrazy', expressions())
    const target = { kind: 'project', id: project.id }
    for (const [tool, args] of [
      ['set_grammar_rules', { text: 'E -> x' }],
      ['set_relation', { stack: '+', input: 'id', relation: '<' }],
      ['clear_relations', {}],
      ['relabel_draft', { label: 'x' }],
      ['discard_draft', {}],
    ] as const) {
      expect((await call(tool, { target, ...args })).error).toMatch(/project.*create_draft/i)
    }
    expect(h.store.getProject(project.id)).toEqual(project)
  })

  it('writes to a snapshot are refused', async () => {
    const project = h.store.createProject('Výrazy', expressions())
    const snap = h.store.createSnapshot(project.id, 'Verzia')!
    expect((await call('set_grammar_rules', { target: { kind: 'snapshot', id: snap.id }, text: 'E -> x' })).error).toMatch(/snapshot/i)
  })

  it('writes to an ended draft are refused', async () => {
    const { target } = await newDraft()
    await call('discard_draft', { target })
    for (const [tool, args] of [
      ['set_grammar_rules', { text: 'E -> x' }],
      ['set_prec_terminals', { terminals: ['x'] }],
      ['relabel_draft', { label: 'x' }],
      ['discard_draft', {}],
    ] as const) {
      expect((await call(tool, { target, ...args })).error).toMatch(/discarded.*read-only/i)
    }
  })

  it('there is no adopt tool', async () => {
    const { target } = await newDraft()
    const res = await call('adopt_draft', { target })
    expect(res.error ?? res.protocolError).toMatch(/adopt_draft/)
  })

  it('an unknown draft id gives a clear error', async () => {
    expect((await call('get_part', { target: { kind: 'draft', id: 'nope' }, part: 'definition' })).error).toMatch(/no draft.*nope.*list_drafts/i)
  })
})

describe('reading a draft', () => {
  it("read tools accept a draft target; export naming and simulation inputs come from its project", async () => {
    const { project, target } = await newDraft()
    await call('set_grammar_rules', { target, text: FIXED_GRAMMAR })

    const settings = await call('get_project_settings', { target })
    expect(settings.target).toEqual({ kind: 'draft', id: target.id, projectId: project.id, label: 'Oprava konfliktu', state: 'open', revision: 2 })
    expect(settings.simulationInputs).toEqual({ ll: 'id + id', prec: 'id' })
    expect(settings.exportNaming.nonterminalPrefix).toBe('N_')

    expect((await call('simulate_ll', { target, input: 'id + id' })).ok).toBe(true)
    expect((await call('export', { target, kind: 'll-c' })).text).toContain('N_')
    expect((await call('get_sets', { target })).nonterminals.map((n: { nonterminal: string }) => n.nonterminal)).toEqual(['E', 'R'])
    expect(h.store.getDraft(target.id)!.revision).toBe(2)
  })

  it("a draft's snapshots are listed through the draft target", async () => {
    const { target } = await newDraft()
    await call('set_grammar_rules', { target, text: FIXED_GRAMMAR })
    expect((await call('list_snapshots', { target })).snapshots.map((s: { kind: string }) => s.kind)).toEqual(['auto'])
  })
})
